INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'iron-pulse-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Iron Pulse in Juffair.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من نبض الحديد في Juffair.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"High-performance training facility offering coached strength classes, recovery cold plunges, and an athletic nutrition shop. Focusing on Unlimited Monthly Club Membership, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نادي تدريب عالي الأداء يقدم حصص القوة البدنية والاستشفاء ومتجر المكملات الرياضية. من خلال خدمة عضوية النادي الشهرية المفتوحة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>High-performance training facility offering coached strength classes, recovery cold plunges, and an athletic nutrition shop.</p><p>Focusing on <strong>Unlimited Monthly Club Membership</strong>, our Juffair specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>نادي تدريب عالي الأداء يقدم حصص القوة البدنية والاستشفاء ومتجر المكملات الرياضية.</p><p>من خلال خدمة <strong>عضوية النادي الشهرية المفتوحة</strong>، يعمل فريقنا في Juffair على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Iron Pulse', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | نبض الحديد', 'Executive guide by Iron Pulse covering Unlimited Monthly Club Membership benchmarks in Bahrain.', 'دليل تنفيذي من نبض الحديد حول معايير عضوية النادي الشهرية المفتوحة في البحرين.', 'Sustainability', '{"fitness","sustainability","Juffair","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
